 SeekBar light=new SeekBar(this);light.setMax(200);light.setProgress(100);panel.addView(light);light.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean u){brightness[0]=p-100;filter.run();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});
