 new AlertDialog.Builder(this).setTitle(item.name).setView(panel).setNegativeButton("Tutup",null).setPositiveButton("Simpan salinan",(d,w)->{Bitmap b=current[0];android.graphics.ColorFilter cf=im.getColorFilter();worker.execute(()->saveEdited(b,cf));}).show();
